    auto sizes = x.sizes().vec();
    sizes[1] = x.size(1) + y.size(1); // C拼接
    at::Tensor result = at::empty(sizes, x.options());
    EXEC_NPU_CMD(aclnnSqueezeNetCustom, x.contiguous(), y.contiguous(), result);
    return result;
}

